        else {filter[0][0]=.393f;filter[1][0]=.769f;filter[2][0]=.189f;filter[0][1]=.349f;filter[1][1]=.686f;filter[2][1]=.168f;filter[0][2]=.272f;filter[1][2]=.534f;filter[2][2]=.131f;for(int i=0;i<3;i++)for(int j=0;j<3;j++)filter[i][j]*=.85f;filter[4][0]=.055f;filter[4][1]=.04f;filter[4][2]=.025f;}
        float amount=Math.Max(0,Math.Min(100,mark.ImageFilterStrength))/100;for(int i=0;i<5;i++)for(int j=0;j<5;j++){float identity=i==j?1:0;filter[i][j]=identity+(filter[i][j]-identity)*amount;}var result=new float[5][];for(int i=0;i<5;i++){result[i]=new float[5];for(int j=0;j<5;j++)for(int k=0;k<5;k++)result[i][j]+=general[i,k]*filter[k][j];}return new ColorMatrix(result);
    }
}
